{
  "aktywnosci": [
    {
      "tytul": "Detektywi barw – poszukiwanie kolorów podstawowych w sali",
      "opis": "Nauczyciel układa na dywanie trzy duże obręcze w kolorach: czerwonym, żółtym i niebieskim, a następnie zaprasza dzieci do zabawy w tropicieli barw. Przedszkolaki spacerują po sali i wyszukują bezpieczne przedmioty, klocki lub zabawki odpowiadające barwom podstawowym, po czym odkładają je do właściwej obręczy. Na koniec grupa wspólnie z nauczycielem sprawdza zawartość obręczy i nazywa odnalezione przedmioty oraz ich kolory."
    },
    {
      "tytul": "Kolorowe domki – zabawa ruchowa z szarfami przy muzyce",
      "opis": "Nauczyciel rozdaje dzieciom szarfy w trzech barwach podstawowych, a w różnych częściach sali wyznacza czerwony, żółty i niebieski domek z ułożonych na podłodze materiałów. Dzieci tańczą i biegają swobodnie po sali w rytm tamburynu lub prostej piosenki. Na przerwę w muzyce nauczyciel unosi do góry szarfę w wybranym kolorze, a dzieci posiadające ten sam kolor jak najszybciej biegną do odpowiedniego domku."
    },
    {
      "tytul": "Trzy krainy – stemplowanie plakatami barw podstawowych",
      "opis": "Nauczyciel przygotowuje dla dzieci kartki podzielone na trzy części oraz miseczki z farbami: czerwoną, żółtą i niebieską wraz z gąbkami do stemplowania. Zadaniem przedszkolaków jest wypełnienie każdego pola odbitkami pieczątek w jednym, nienakładającym się kolorze podstawowym. Gotowe prace zostają powieszone w galerii przedszkolnej jako barwne plansze wprowadzające w tematykę tygodnia."
    }
  ]
}
